import{z as l,x as i,o as r,c,q as E,j as t,D as e,d as A,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"GPU 存储层次","description":"","frontmatter":{"title":"GPU 存储层次","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-memory-hierarchy.md","filePath":"cs/gpu-memory-hierarchy.md","lastUpdated":1791413859000}'),p={name:"cs/gpu-memory-hierarchy.md"};function d(h,a,B,m,D,_){const s=i("Mermaid");return r(),c("div",null,[a[2]||(a[2]=E('<h1 id="gpu-存储层次" tabindex="-1">GPU 存储层次 <a class="header-anchor" href="#gpu-存储层次" aria-label="Permalink to &quot;GPU 存储层次&quot;">​</a></h1><div class="epigraph"><p>寄存器、共享存储、L1/L2、HBM 的容量与延迟差几个数量级；SIMT 用占用率换延迟隐藏，但带宽仍要程序把访问打到对的那一层。</p><footer>—— 据 NVIDIA CUDA 编程指南中的硬件模型；Lindholm et al., IEEE Micro 2008；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/gpu-simt">上一课</a> 用切 warp 藏延迟，没说数据住哪。CPU 的 <a href="/cs/locality-principle">局部性</a> 与 <a href="/cs/mesi-protocol">MESI</a> 不能原样搬来：GPU 的「共享存储」是程序员可见的暂存，一致性模型更弱。本课不重讲 warp 调度。缺口是<strong>层次：寄存器堆、scratchpad、cache、设备内存，以及它们如何限制占用率。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HBM 带宽高、延迟仍几十到上百 ns。若每个线程每次运算都打 HBM，切 warp 也不够。缺口不是再加 CPU 式的 8 路 L1，而是<strong>把热数据放进每 SM 的共享存储或寄存器，cache 当作自动的那一层，并承认寄存器文件大小直接限制驻留 warp 数。</strong></p><p><span class="marginnote">共享存储（scratchpad）按 bank 组织，冲突会串行化——下一课合并与本课 bank 是带宽的两面。L2 常片上共享，跨 SM 的原子在这里汇合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器把私有变量放寄存器；程序员或编译器把协作缓冲放 shared；其余走全局内存，硬件 cache 可选。占用率：每个 warp 的寄存器数 × warp 数 ≤ 物理堆；shared 用量同样设上限。原子与栅栏在 SM 内走共享存储或 L1；跨 SM 走 L2。</p>',8)),(r(),t(n,null,{default:e(()=>[o(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%AF%8F%E7%BA%BF%E7%A8%8B%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20SM%5B%22%E5%8D%A0%E7%94%A8%E7%8E%87%E4%B8%8A%E9%99%90%22%5D%0A%20%20SHM%5B%22%E5%85%B1%E4%BA%AB%E5%AD%98%E5%82%A8%20scratchpad%22%5D%20--%3E%20SM%0A%20%20L1%5B%22L1%20%2F%20%E7%BA%B9%E7%90%86%22%5D%20--%3E%20L2%5B%22%E7%89%87%E4%B8%8A%20L2%22%5D%0A%20%20L2%20--%3E%20HBM%5B%22%E8%AE%BE%E5%A4%87%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 CPU：<a href="/cs/vipt-cache">VIPT</a> 仍可能出现在 I-cache/D-cache，但 GPU 更强调带宽而非单线程命中延迟。一致性：许多 GPU 对全局内存提供较弱保证，需要显式栅栏与内存空间限定——对应 CPU 的 <a href="/cs/fence-cost">fence</a>，但粒度是 warp/block。不要把这里写成训练用的 HBM 容量规划；本课只给硬件层次。</p><p>占用率与延迟隐藏是一对：驻留 warp 太少，一次 shared miss 就露馅；寄存器分配过狠则驻留掉下去。编译器报告的 occupancy 是这一层的可读接口，不是 ISA。</p><p><span class="marginnote">数字实例：A100 每 SM 的寄存器堆是 65536 个 32 位寄存器。若核函数经编译器报告每线程用 64 个寄存器，一块 SM 最多驻留 65536 ÷ 64 = 1024 线程；若优化后涨到 128 个，驻留立即腰斩到 512 线程——寄存器不是「越多越好」的免费资源，它直接从占用率里扣钱。</span></p><p><span class="marginnote">常见误区：初学者容易把 GPU 的共享存储当成「一块自动管理的缓存」。它恰恰相反：放置与同步全由程序员负责，写错 bank、忘加栅栏硬件都不替你兜底。换来的是确定性与极低延迟——它是「程序员可见的暂存」，不是 cache 的替身。</span></p>',5)),(r(),t(n,null,{default:e(()=>[o(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20K%5B%22%E7%83%AD%E6%95%B0%E6%8D%AE%E6%AF%8F%E8%BD%AE%E8%A2%AB%E5%85%A8%20block%20%E8%AF%BB%22%5D%20--%3E%20DEC%7B%22%E6%94%BE%E5%93%AA%E5%B1%82%22%7D%0A%20%20DEC%20--%3E%7C%22%E5%85%A8%E5%B1%80%20HBM%22%7C%20SLOW%5B%22%E6%AF%8F%E6%AC%A1%E5%87%A0%E5%8D%81%E4%B8%8A%E7%99%BE%20ns%20warp%20%E5%88%87%E4%B8%8D%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20DEC%20--%3E%7C%22smem%20%E7%89%87%E4%B8%8A%22%7C%20FAST%5B%22%E4%B8%80%E6%AC%A1%E6%8B%B7%E5%85%A5%0A%20%20%E5%90%8E%E7%BB%AD%E7%BA%B3%E7%A7%92%E7%BA%A7%E5%A4%8D%E7%94%A8%22%5D%0A%20%20DEC%20--%3E%7C%22%E5%AF%84%E5%AD%98%E5%99%A8%22%7C%20FAST2%5B%22%E9%9B%B6%E7%AD%89%E5%BE%85%20%E4%BD%86%E6%8C%A4%E5%8D%A0%E9%A9%BB%E7%95%99%20warp%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每代芯片的 KiB 数当考试。分支发散下一课会让部分 lane 关掉，有效带宽再打折。合并访存再下一课：全局 load 如何合成少量事务。</p><p>后课默认：寄存器与 shared 决定能藏多少延迟。控制流不一致会让一部分 lane 空转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GPU 层次是寄存器 / scratchpad / cache / HBM；占用率绑在前两层。</li><li>切 warp 藏延迟，带宽仍靠数据放对层。</li><li>分支让共享 PC 破裂，下一课发散。</li><li>出处：Lindholm et al.；CUDA 硬件模型；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',5))])}const C=l(p,[["render",d]]);export{P as __pageData,C as default};
